# New specifier types for the release
class Auto(object):
    """Auto is a specifier type that allows glom to automatically
    determine the appropriate operation based on the target and context.

    When Auto is used in a spec, glom will apply automatic type inference
    and transformation.
    """
    def glomit(self, target, scope):
        return target

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s()' % (cn,)


class Fill(object):
    """Fill is a specifier type that fills in default values for missing
    keys or attributes in the target.

    Args:
       spec: The spec to fill
       default: The default value to use when a value is missing
    """
    def __init__(self, spec, default=None):
        self.spec = spec
        self.default = default

    def glomit(self, target, scope):
        try:
            return scope[glom](target, self.spec, scope)
        except GlomError:
            if self.default is not None:
                return self.default
            raise

    def __repr__(self):
        cn = self.__class__.__name__
        if self.default is not None:
            return '%s(%r, default=%r)' % (cn, self.spec, self.default)
        return '%s(%r)' % (cn, self.spec)


class Iter(object):
    """Iter is a specifier type that iterates over the target and
    applies a subspec to each item.

    Args:
       subspec: The spec to apply to each item
    """
    def __init__(self, subspec):
        self.subspec = subspec

    def glomit(self, target, scope):
        ret = []
        for item in target:
            val = scope[glom](item, self.subspec, scope)
            ret.append(val)
        return ret

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%r)' % (cn, self.subspec)


class Let(object):
    """Let is a specifier type that binds values to names in the scope
    for use within a subspec.

    Args:
       **bindings: keyword arguments mapping names to specs/values
    """
    def __init__(self, **bindings):
        self.bindings = bindings

    def glomit(self, target, scope):
        new_scope = dict(scope)
        for name, subspec in self.bindings.items():
            new_scope[name] = scope[glom](target, subspec, scope)
        return scope[glom](target, self.spec, new_scope)

    def __repr__(self):
        cn = self.__class__.__name__
        return '%s(%s)' % (cn, ', '.join('%s=%r' % (k, v) for k, v in self.bindings.items()))


class Invoke(object):
    """Invoke is a specifier type that invokes a callable on the target.

    Args:
       func: A callable to invoke on the target
       args: Additional positional arguments
       kwargs: Additional keyword arguments
    """
    def __init__(self, func, args=None, kwargs=None):
        self.func = func
        self.args = args if args is not None else ()
        self.kwargs = kwargs if kwargs is not None else {}

    def glomit(self, target, scope):
        return self.func(target, *self.args, **self.kwargs)

    def __repr__(self):
        cn = self.__class__.__name__
        if self.args or self.kwargs:
            return '%s(%r, args=%r, kwargs=%r)' % (cn, self.func, self.args, self.kwargs)
        return '%s(%r)' % (cn, self.func)


